/** Whether a Version's VGA script opcodes are 16 bits wide. */
export function vgaHasWideOpcodes(table: string): boolean {
  // The opposite grouping from the game bytecode's, which is why it is a
  // function here rather than a reuse of `hasWideOpcodes`.
  return table !== 'simon2' && table !== 'feeblefiles' && table !== 'puzzlepack';
}

/** The word that ends a `q` operand's list of pairs. */
export function vgaPairTerminator(table: string): number {
  return table === 'feeblefiles' || table === 'puzzlepack' ? 9999 : 999;
}
